    transparent = contrast_ratio("transparent", "#000000"),
    short_hex = contrast_ratio(c("#abc", "#123456"), "white"),
    near_white_apca = contrast_ratio("#fefefe", "#ffffff", algorithm = "APCA")
  )
}

